```python
from __future__ import annotations

import sqlite3
from pathlib import Path

NUM_SHARDS = 4
TIMESTAMPS = (
    "2026-06-19T12:00:00Z",
    "2026-06-19T12:00:01Z",
    "2026-06-19T12:00:02Z",
)


def fixture_rows() -> list[tuple[int, str, float]]:
    return [
        (sensor_id, recorded_at, 20.0 + sensor_id / 10 + offset)
        for sensor_id in range(8)
        for offset, recorded_at in enumerate(TIMESTAMPS)
    ]


def shard_path(root: Path, shard_id: int) -> Path:
    return root / f"sensor_shard_{shard_id}.db"


def initialize(root: Path) -> None:
    root.mkdir(parents=True, exist_ok=True)
    for shard_id in range(NUM_SHARDS):
        with sqlite3.connect(shard_path(root, shard_id)) as connection:
            connection.execute(
                """
                CREATE TABLE IF NOT EXISTS readings (
                    id INTEGER PRIMARY KEY,
                    sensor_id INTEGER NOT NULL,
                    recorded_at TEXT NOT NULL,
                    value_c REAL NOT NULL
                )
                """
            )
            connection.execute(
                "CREATE INDEX IF NOT EXISTS readings_by_sensor_time "
                "ON readings (sensor_id, recorded_at)"
            )


def route_sensor(sensor_id: int) -> int:
    return sensor_id % NUM_SHARDS


def load_fixture(root: Path) -> None:
    connections = {
        shard_id: sqlite3.connect(shard_path(root, shard_id))
        for shard_id in range(NUM_SHARDS)
    }
    try:
        for sensor_id, recorded_at, value_c in fixture_rows():
            connections[route_sensor(sensor_id)].execute(
                "INSERT INTO readings (sensor_id, recorded_at, value_c) VALUES (?, ?, ?)",
                (sensor_id, recorded_at, value_c),
            )
        for connection in connections.values():
            connection.commit()
    finally:
        for connection in connections.values():
            connection.close()


def open_all_shards(root: Path) -> sqlite3.Connection:
    connection = sqlite3.connect(":memory:")
    try:
        for shard_id in range(NUM_SHARDS):
            # Schema identifiers are fixed application constants; only the path is data.
            connection.execute(
                f"ATTACH DATABASE ? AS shard{shard_id}",
                (str(shard_path(root, shard_id)),),
            )
    except Exception:
        connection.close()
        raise
    return connection


def read_sensor(
    root: Path, sensor_id: int, start: str, end: str
) -> list[tuple[str, float]]:
    shard_id = route_sensor(sensor_id)
    with sqlite3.connect(shard_path(root, shard_id)) as connection:
        return connection.execute(
            """
            SELECT recorded_at, value_c
            FROM readings
            WHERE sensor_id = ? AND recorded_at >= ? AND recorded_at < ?
            ORDER BY recorded_at
            """,
            (sensor_id, start, end),
        ).fetchall()


def read_day_across_shards(
    root: Path, start: str, end: str
) -> list[tuple[int, str, float]]:
    branches = [
        f"SELECT sensor_id, recorded_at, value_c FROM shard{shard_id}.readings "
        "WHERE recorded_at >= ? AND recorded_at < ?"
        for shard_id in range(NUM_SHARDS)
    ]
    statement = " UNION ALL ".join(branches) + " ORDER BY sensor_id, recorded_at"
    parameters = tuple(value for _ in range(NUM_SHARDS) for value in (start, end))
    connection = open_all_shards(root)
    try:
        return connection.execute(statement, parameters).fetchall()
    finally:
        connection.close()


def query_plan(
    root: Path, sensor_id: int, start: str, end: str
) -> list[str]:
    shard_id = route_sensor(sensor_id)
    with sqlite3.connect(shard_path(root, shard_id)) as connection:
        rows = connection.execute(
            """
            EXPLAIN QUERY PLAN
            SELECT recorded_at, value_c
            FROM readings
            WHERE sensor_id = ? AND recorded_at >= ? AND recorded_at < ?
            ORDER BY recorded_at
            """,
            (sensor_id, start, end),
        ).fetchall()
    return [row[3] for row in rows]
```

