SELECT create_reference_table('plans');

SET citus.shard_count = 8;
SELECT create_distributed_table('tenants', 'tenant_id');
SELECT create_distributed_table('projects', 'tenant_id', colocate_with => 'tenants');
SELECT create_distributed_table('tasks', 'tenant_id', colocate_with => 'tenants');

ALTER TABLE tenants
  ADD PRIMARY KEY (tenant_id);
ALTER TABLE projects
  ADD PRIMARY KEY (tenant_id, project_id);
ALTER TABLE tasks
  ADD PRIMARY KEY (tenant_id, task_id);

ALTER TABLE tenants
  ADD CONSTRAINT tenants_plan_code_fkey
  FOREIGN KEY (plan_code) REFERENCES plans (plan_code);
ALTER TABLE projects
  ADD CONSTRAINT projects_tenant_id_fkey
  FOREIGN KEY (tenant_id) REFERENCES tenants (tenant_id);
ALTER TABLE tasks
  ADD CONSTRAINT tasks_tenant_project_fkey
  FOREIGN KEY (tenant_id, project_id)
  REFERENCES projects (tenant_id, project_id);
```

Carrying `tenant_id` in each distributed foreign key makes the referenced rows colocated on the same shard. It lets Citus enforce the relationship and execute tenant-scoped project/task joins as a single-shard task.

Use a non-login owner for database objects and a non-owner, non-`BYPASSRLS` login for application queries. The policy compares every row with a transaction-local tenant setting: `USING` limits existing rows visible to reads, updates, and deletes, while `WITH CHECK` rejects inserted or updated row values for another tenant.

Save the completed `setup.sql` as follows:

```sql
-- setup.sql
DROP SCHEMA IF EXISTS rls_lab CASCADE;
DROP ROLE IF EXISTS rls_lab_app;
DROP ROLE IF EXISTS rls_lab_owner;

CREATE ROLE rls_lab_owner NOLOGIN;
CREATE ROLE rls_lab_app
  LOGIN
  NOBYPASSRLS
  PASSWORD 'rls-app-password';

CREATE SCHEMA rls_lab AUTHORIZATION rls_lab_owner;

SET ROLE rls_lab_owner;

CREATE TABLE rls_lab.projects (
  id bigint GENERATED ALWAYS AS IDENTITY,
  tenant_id uuid NOT NULL,
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, id),
  UNIQUE (tenant_id, name)
);

INSERT INTO rls_lab.projects (tenant_id, name) VALUES
  ('11111111-1111-1111-1111-111111111111', 'Alpha project'),
  ('22222222-2222-2222-2222-222222222222', 'Beta project');

ALTER TABLE rls_lab.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE rls_lab.projects FORCE ROW LEVEL SECURITY;

CREATE POLICY projects_tenant_isolation
ON rls_lab.projects
FOR ALL
TO rls_lab_app
USING (
  tenant_id =
  NULLIF(current_setting('app.tenant_id', true), '')::uuid
)
WITH CHECK (
  tenant_id =
  NULLIF(current_setting('app.tenant_id', true), '')::uuid
);

RESET ROLE;

GRANT USAGE ON SCHEMA rls_lab TO rls_lab_app;
GRANT SELECT, INSERT, UPDATE, DELETE
  ON rls_lab.projects TO rls_lab_app;
GRANT USAGE, SELECT ON ALL SEQUENCES
  IN SCHEMA rls_lab TO rls_lab_app;
```

Apply the file with `docker exec -i lab-ch7-p7 psql -v ON_ERROR_STOP=1 -U postgres -d ch7_rls_lab < setup.sql`, then inspect the effective role and verify tenant A's read plus transaction cleanup:

```sql
SET ROLE rls_lab_app;

SELECT
  current_user,
  session_user,
  rolsuper,
  rolbypassrls
FROM pg_roles
WHERE rolname = current_user;
-- current_user=rls_lab_app, rolsuper=false, rolbypassrls=false

BEGIN;
SELECT set_config(
  'app.tenant_id',
  '11111111-1111-1111-1111-111111111111',
  true
);
SELECT
  array_agg(name ORDER BY name) AS visible_projects,
  count(DISTINCT tenant_id) AS visible_tenants
FROM rls_lab.projects;
-- only Alpha project; visible_tenants=1
COMMIT;

SELECT
  NULLIF(current_setting('app.tenant_id', true), '') IS NULL
  AS tenant_context_cleared;
-- true

SELECT count(*) AS rows_without_tenant_context
FROM rls_lab.projects;
-- 0: missing context fails closed

RESET ROLE;
```

Run the forbidden write interactively so the expected error does not stop the rest of a setup script:

```sql
SET ROLE rls_lab_app;
BEGIN;
SELECT set_config(
  'app.tenant_id',
  '11111111-1111-1111-1111-111111111111',
  true
);
INSERT INTO rls_lab.projects (tenant_id, name)
VALUES (
  '22222222-2222-2222-2222-222222222222',
  'Illegal project'
);
-- ERROR: new row violates row-level security policy for table projects
ROLLBACK;
RESET ROLE;
